/// Removes a directory like `Mount::rmdir` and reports the victim.
pub fn rmdir_tracked(&self, name: &str, cred: &Cred) -> VfsResult<Option<RemovedEntry>> {
    self.check_writable_mount()?;
    let mut removed = None;
    self.dentry.as_dir()?.rmdir_with(name, |victim| {
        self.may_modify_directory(cred)?;
        let victim_path = self.with_dentry(victim.clone());
        self.check_sticky(&victim_path, cred)?;
        victim_path.check_not_mountpoint()?;
        removed = Some(RemovedEntry {
            parent: self.inode(),

            victim_nlink: Some(
                victim_path
                    .getattr()
                    .map_or_else(|_| victim_path.identity().nlink, |meta| meta.nlink),
            ),
            victim_dentry: victim.clone(),
        });
        Ok(())
    })?;
    Ok(removed)
}

/// Retains a hashed dentry until it is explicitly evicted from the dcache.
pub(crate) fn cache_dentry(&self, dentry: Dentry) {
    let key = dentry.key();
    let replaced = self.dentry_cache.lock().insert(key, dentry);
    drop(replaced);
}

/// Removes a dentry from the dcache without affecting external references.
pub(crate) fn uncache_dentry(&self, dentry: &Dentry) {
    let key = dentry.key();
    let removed = self.dentry_cache.lock().remove(&key);
    drop(removed);
}

/// Returns whether `dentry` is currently retained by the dcache.
#[cfg(unittest)]
pub(crate) fn is_dentry_cached(&self, dentry: &Dentry) -> bool {
    self.dentry_cache.lock().contains_key(&dentry.key())
}

